std = X_train.std(axis=0)
std[std < 1e-8] = 1.0
X_train = (X_train - mean) / std
X_test = (X_test - mean) / std

n, d = X_train.shape

# Implement a proper decision tree
def gini(y):
    if len(y) == 0:
        return 0
    p1 = y.mean()
    return 1 - p1**2 - (1-p1)**2

def best_split(X, y, min_samples=2):
