    best_fi, best_t = 0, 0
    base_impurity = gini(y) * len(y)
    for fi in range(X.shape[1]):
        vals = np.unique(X[:, fi])
        for i in range(len(vals)-1):
            t = (vals[i] + vals[i+1]) / 2
            left = y[X[:, fi] <= t]
            right = y[X[:, fi] > t]
            if len(left) < min_samples or len(right) < min_samples:
                continue
            gain = base_impurity - gini(left)*len(left) - gini(right)*len(right)
            if gain > best_gain:
                best_gain = gain
                best_fi, best_t = fi, t
    return best_fi, best_t, best_gain

def build_tree(X, y, depth=0, max_depth=3, min_samples=2):
