        return {'leaf': True, 'value': int(y.mean() >= 0.5)}

    fi, t, gain = best_split(X, y, min_samples)
    if gain <= 0:
        return {'leaf': True, 'value': int(y.mean() >= 0.5)}

    left_mask = X[:, fi] <= t
    right_mask = ~left_mask

    if left_mask.sum() < min_samples or right_mask.sum() < min_samples:
        return {'leaf': True, 'value': int(y.mean() >= 0.5)}

    return {
        'leaf': False, 'fi': fi, 't': t,
        'left': build_tree(X[left_mask], y[left_mask], depth+1, max_depth, min_samples),
        'right': build_tree(X[right_mask], y[right_mask], depth+1, max_depth, min_samples)
    }

def tree_predict_one(x, node):
    if node['leaf']:
        return node['value']
    if x[node['fi']] <= node['t']:
        return tree_predict_one(x, node['left'])
    else:
        return tree_predict_one(x, node['right'])

def tree_predict(X, node):
    return np.array([tree_predict_one(x, node) for x in X])

